using System;
using System.Collections.Generic;
using System.IO;
using PokeLab.Overworld;
using PokeLab.Overworld.People;
using PokeLab.Overworld.World;
using Unity.AI.Navigation;
using UnityEngine.AI;
using UnityEditor;
using UnityEngine;

namespace PokeLab.Boot.Editor
{
    /// <summary>
    /// Builds the playable scene from the designed layout.
    ///
    /// The layout is data, not a scene, deliberately: it is generated by a seeded script
    /// and regenerated whenever the design changes, so hand-placing it once would throw
    /// that away. This reads the flattened form produced by
    /// <c>Tools/Level/emit_unity_layout.py</c> and rebuilds the whole thing in one pass.
    ///
    /// The terrain arrives as one continuous surface split into chunks, sampled from the
    /// baked height grid that every object's Y was taken from. It used to arrive as flat
    /// polygonal "decks" held at a constant height, which is why the world looked like
    /// plates laid on top of each other; there is no deck concept in the design and there
    /// is none here now.
    ///
    /// Normals come from the emitter rather than from RecalculateNormals, because each
    /// chunk would otherwise compute a one-sided derivative along its shared edge and
    /// leave a lighting seam on every chunk boundary.
    /// </summary>
    public static class LevelLayoutBuilder
    {
        private const string LayoutDir = "Assets/Game/Data/Levels/";
        private const string RootName = "Level";

        /// <summary>
        /// Which emitted layout belongs to which scene.
        ///
        /// The slice is emitted per scene rather than as one map: the zones already have
        /// different rules -- the town's encounter rate is zero and it has its own
        /// ambience -- and one scene means one height field where the town's building
        /// pads and the route's cliffs fight over the same grid, one lighting rig for
        /// two moods, and everything in both loaded at once.
        /// </summary>
        private static readonly (string Scene, string Layout)[] SceneLayouts =
        {
            ("Town", "slice_town_unity.json"),
            ("Field", "slice_field_unity.json"),
        };

        private static string LayoutFor(string sceneName)
        {
            foreach (var (scene, layout) in SceneLayouts)
                if (string.Equals(scene, sceneName, StringComparison.OrdinalIgnoreCase))
                    return LayoutDir + layout;
            return LayoutDir + "slice_layout_unity.json";
        }

        private const string TerrainMaterial =
            "Assets/Game/Art/Environment/Terrain/Materials/M_Ground_TerrainBlend.mat";
        private const string WaterMaterial =
            "Assets/Game/Shaders/Materials/M_Water_Lake.mat";
        private const string FoliageMaterial =
            "Assets/Game/Art/Environment/Foliage/Materials/M_Env_Foliage.mat";

        [MenuItem("Tools/Poké Lab/Level/Build Slice Layout")]
        public static void Build() => Build(null);

        /// <summary>Builds a named scene's layout, or the one matching the open scene.</summary>
        public static void Build(string sceneName)
        {
            var open = UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene().name;
            var band = string.IsNullOrEmpty(sceneName) ? open : sceneName;
            var layoutPath = LayoutFor(band);

            if (!File.Exists(layoutPath))
            {
                Debug.LogError($"[Level] {layoutPath} not found. Run Tools/Level/emit_unity_layout.py first.");
                return;
            }

            var layout = JsonUtility.FromJson<Layout>(File.ReadAllText(layoutPath));
            if (layout == null || layout.ground == null || layout.ground.Length == 0)
            {
                Debug.LogError("[Level] Layout parsed but carried no ground. Expected " +
                               "schema pokelab-level-unity/2 — re-run the emitter.");
                return;
            }

            var existing = GameObject.Find(RootName);
            if (existing != null) UnityEngine.Object.DestroyImmediate(existing);

            var root = new GameObject(RootName);
            var parents = new Dictionary<string, Transform>();
            var missing = new HashSet<string>();
            var stats = new Stats();

            try
            {
                BuildGround(layout, root.transform, parents);
                BuildWater(layout, root.transform, parents);
                BuildObjects(layout, root.transform, parents, missing);
                BuildFoliage(layout, root.transform, parents, missing, stats);
                BuildTallGrass(layout, root.transform, parents);
                BuildCaveEntrances(layout, root.transform, parents);
                BuildBarriers(layout, root.transform, parents);
                BuildSceneLinks(layout, root.transform, parents);
                BuildBuildingDoors(layout, root.transform, parents);
                BuildPeople(layout, root.transform, parents);
                BuildAnchors(layout, root.transform, parents);
                BuildSpawn(layout, root.transform);
                BuildCast(layout, root.transform, parents, band);
                // After BuildCast, which is what stands the professor up: an encounter armed
                // on an actor the previous step has not created yet finds nothing to hang on.
                BuildStoryTriggers();
                BuildStoryGate(layout, root.transform, parents);
                BuildNavigation(root);
            }
            finally
            {
                EditorUtility.ClearProgressBar();
            }

            if (missing.Count > 0)
            {
                Debug.LogWarning($"[Level] {missing.Count} asset path(s) could not be loaded. " +
                                 "Those entries were skipped:\n  " + string.Join("\n  ", missing));
            }

            // Persist it. The builder runs in memory and nothing was saving the result,
            // so the scene on disk held a camera and an empty spawn marker: pressing Play
            // reloaded from disk and showed nothing at all. It never surfaced because the
            // capture tool builds and renders in the same session, so every review frame
            // was of a level that existed only for as long as the capture took.
            var scene = UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
            UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
            UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);

            Debug.Log(
                $"[Level] Built '{RootName}': {layout.ground.Length} ground chunks " +
                $"({stats.GroundTriangles} tris), {layout.water?.Length ?? 0} water, " +
                $"{layout.objects?.Length ?? 0} objects, {stats.FoliageInstances} foliage " +
                $"instances in {stats.FoliageGroups} instanced group(s), " +
                $"{layout.tallGrass?.Length ?? 0} grass triggers, " +
                $"{layout.caveEntrances?.Length ?? 0} cave entrance(s), " +
                $"{layout.barrierVolumes?.Length ?? 0} barrier(s), " +
                $"{layout.sceneLinks?.Length ?? 0} scene link(s), " +
                $"{layout.buildingDoors?.Length ?? 0} building door(s), " +
                $"{layout.npcs?.Length ?? 0} npc(s), {layout.trainers?.Length ?? 0} trainer(s), " +
                $"{layout.ambientAnchors?.Length ?? 0} anchors.");
        }

        private sealed class Stats
        {
            public int GroundTriangles;
            public int FoliageInstances;
            public int FoliageGroups;
        }

        /// <summary>
        /// Bakes navigation over the level that was just built.
        ///
        /// This has to happen here rather than being a one-off in the scene. The terrain
        /// is generated: every regeneration moves the ground, and a bake from before it
        /// covers geometry that no longer exists. The symptom is not subtle but it is
        /// misleading — NavMeshAgent throws "can only be called on an active agent that
        /// has been placed on a NavMesh" once per frame per NPC, which reads as a bug in
        /// the NPC rather than as stale navigation.
        ///
        /// The surface collects by layer so it follows the same Ground/Environment split
        /// the builder already applies, and it is rebuilt rather than added to, so
        /// removing an object removes what it carved.
        /// </summary>
        /// <summary>
        /// Saves every authored NavMeshAgent switched off.
        ///
        /// RequireComponent puts an agent on each NPC and the scene stores it enabled, so Unity
        /// validates its position while the scene is loading — before any Awake has run — and
        /// logs "Failed to create agent because it is not close enough to the NavMesh" for
        /// every one that sits a few centimetres off the walkable surface. Nothing later can
        /// prevent that, because nothing later has happened yet, and an agent that fails to
        /// create keeps throwing for the rest of the session.
        ///
        /// NpcController already knows how to put one right: it samples the navmesh in Awake
        /// and enables the agent afterwards. All this has to do is make sure the agent is not
        /// live before that runs.
        /// </summary>
        private static int DisableAuthoredAgents(GameObject root)
        {
            var disabled = 0;
            foreach (var agent in root.GetComponentsInChildren<UnityEngine.AI.NavMeshAgent>(true))
            {
                if (!agent.enabled) continue;
                agent.enabled = false;
                disabled++;
            }
            return disabled;
        }

        private static void BuildNavigation(GameObject root)
        {
            var quietened = DisableAuthoredAgents(root);
            if (quietened > 0)
                Debug.Log($"[Level] {quietened} NavMeshAgent(s) saved switched off; " +
                          "NpcController places and enables them.");

            var surface = root.GetComponent<NavMeshSurface>();
            if (surface == null) surface = root.AddComponent<NavMeshSurface>();

            surface.collectObjects = CollectObjects.Children;
            surface.useGeometry = NavMeshCollectGeometry.PhysicsColliders;
            var ground = LayerMask.NameToLayer("Ground");
            var environment = LayerMask.NameToLayer("Environment");
            var interactable = LayerMask.NameToLayer("Interactable");
            surface.layerMask = MaskOf(ground) | MaskOf(environment) | MaskOf(interactable);

            // A bake over no layers succeeds and produces nothing, so say so here. Every
            // agent then fails to spawn, and the error it raises names the agent rather
            // than the mask that excluded the entire world.
            if (surface.layerMask == 0)
            {
                Debug.LogError("[Level] None of the navmesh layers (Ground, Environment, " +
                               "Interactable) exist, so the bake has nothing to walk on. " +
                               "Every NPC will report 'not close enough to the NavMesh'.");
            }

            // Matched to PlayerLocomotion so what the agents can walk is what the player
            // can walk. A navmesh built to different limits sends NPCs up slopes the
            // player cannot follow them onto.
            surface.overrideVoxelSize = true;
            surface.voxelSize = 0.12f;

            surface.BuildNavMesh();

            // BuildNavMesh leaves the data in memory. Unless it is written out as an
            // asset it is gone the moment the scene reloads, and every agent then reports
            // "not close enough to the NavMesh" — which reads as a placement fault rather
            // than as navigation that was never saved.
            if (surface.navMeshData != null)
            {
                var scene = UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
                var dir = "Assets/Game/Data/Navigation";
                if (!AssetDatabase.IsValidFolder(dir))
                    AssetDatabase.CreateFolder("Assets/Game/Data", "Navigation");

                var path = $"{dir}/NavMesh-{(string.IsNullOrEmpty(scene.name) ? "Level" : scene.name)}.asset";
                var existing = AssetDatabase.LoadAssetAtPath<UnityEngine.AI.NavMeshData>(path);
                if (existing != null) AssetDatabase.DeleteAsset(path);
                AssetDatabase.CreateAsset(surface.navMeshData, path);
                AssetDatabase.SaveAssets();
                Debug.Log($"[Level] Navigation baked and saved to {path}.");
            }
            else
            {
                Debug.LogWarning("[Level] Navigation produced no data. Nothing on the " +
                                 "Ground, Environment or Interactable layers was walkable, " +
                                 "so every NPC will stand still.");
            }
        }

        private static int MaskOf(int layer) => layer >= 0 ? 1 << layer : 0;

        // --- terrain ------------------------------------------------------------------

        private static void BuildGround(Layout layout, Transform root,
            Dictionary<string, Transform> parents)
        {
            var material = AssetDatabase.LoadAssetAtPath<Material>(TerrainMaterial);
            var parent = ResolveParent(root, parents, "Terrain/Ground");

            foreach (var chunk in layout.ground)
            {
                var mesh = new Mesh { name = chunk.name };
                mesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;

                var count = chunk.vertices.Length / 3;
                var verts = new Vector3[count];
                var norms = new Vector3[count];
                var cols = new Color[count];
                var uvs = new Vector2[count];

                for (var i = 0; i < count; i++)
                {
                    verts[i] = new Vector3(chunk.vertices[i * 3],
                                           chunk.vertices[i * 3 + 1],
                                           chunk.vertices[i * 3 + 2]);
                    norms[i] = new Vector3(chunk.normals[i * 3],
                                           chunk.normals[i * 3 + 1],
                                           chunk.normals[i * 3 + 2]);
                    // RGBA are the terrain shader's grass / dirt / sand / rock weights.
                    // The roads live in here rather than as their own meshes, which is
                    // why there is nothing to z-fight along 191 m of road.
                    cols[i] = new Color(chunk.colors[i * 4], chunk.colors[i * 4 + 1],
                                        chunk.colors[i * 4 + 2], chunk.colors[i * 4 + 3]);
                    uvs[i] = new Vector2(chunk.uvs[i * 2], chunk.uvs[i * 2 + 1]);
                }

                mesh.vertices = verts;
                mesh.normals = norms;
                mesh.colors = cols;
                mesh.uv = uvs;
                mesh.triangles = chunk.triangles;
                mesh.RecalculateTangents();
                mesh.RecalculateBounds();

                var go = new GameObject(chunk.name);
                go.transform.SetParent(parent, false);
                go.AddComponent<MeshFilter>().sharedMesh = mesh;
                var renderer = go.AddComponent<MeshRenderer>();
                if (material != null) renderer.sharedMaterial = material;
                go.AddComponent<MeshCollider>().sharedMesh = mesh;

                go.isStatic = true;
                SetLayer(go, "Ground");
            }
        }

        private static void BuildWater(Layout layout, Transform root,
            Dictionary<string, Transform> parents)
        {
            var material = AssetDatabase.LoadAssetAtPath<Material>(WaterMaterial);
            var parent = ResolveParent(root, parents, "Terrain/Water");

            // Gathered once for the whole layout rather than per body, because a crossing is
            // authored against the water it spans and not against a particular record: the
            // stepping stones are called Lake_SteppingStones_01 and sit on the stream.
            var crossings = CollectCrossings(layout);

            foreach (var body in layout.water ?? Array.Empty<WaterSurface>())
            {
                var mesh = new Mesh { name = body.name };
                mesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;

                var count = body.vertices.Length / 3;
                var verts = new Vector3[count];
                var uvs = new Vector2[count];
                for (var i = 0; i < count; i++)
                {
                    verts[i] = new Vector3(body.vertices[i * 3],
                                           body.vertices[i * 3 + 1],
                                           body.vertices[i * 3 + 2]);
                    uvs[i] = new Vector2(body.uvs[i * 2], body.uvs[i * 2 + 1]);
                }

                mesh.vertices = verts;
                mesh.uv = uvs;
                mesh.triangles = body.triangles;
                mesh.RecalculateNormals();
                mesh.RecalculateTangents();
                mesh.RecalculateBounds();

                var go = new GameObject(body.name);
                go.transform.SetParent(parent, false);
                go.AddComponent<MeshFilter>().sharedMesh = mesh;
                var renderer = go.AddComponent<MeshRenderer>();
                if (material != null) renderer.sharedMaterial = material;

                // Solid, and the comment that used to sit here claiming otherwise — "a
                // trigger, not a solid ... the player is stopped by the bank, which is
                // terrain" — was wrong on both halves. Nothing ever set isTrigger, so this
                // has always been collision the player can be caught by, and the bank is not
                // what stops them: the curtain below is.
                //
                // It stays solid because it cannot be anything else. A MeshCollider has to be
                // convex to be a trigger, and the convex hull of a meandering stream ribbon
                // is a slab covering every field it winds through, while the lake's hull
                // bridges its own bays. Either would be a water trigger over dry land.
                //
                // With the waterline walled that is no longer a trap: nothing reaches this
                // surface until the party can surf, and once it can, riding along the top of
                // the water is exactly what surfing looks like. WaterBody, when it is finally
                // put on these, will want a trigger and will have to bring its own — a box or
                // a convex proxy, not this mesh.
                var collider = go.AddComponent<MeshCollider>();
                collider.sharedMesh = mesh;
                collider.convex = false;

                go.isStatic = true;
                SetLayer(go, "Water");

                BuildShoreline(body, mesh, go.transform, crossings);
            }
        }

        /// <summary>
        /// Raises a wall along the waterline that the player cannot walk through, and leaves
        /// a gap in it wherever there is something authored to cross on.
        ///
        /// The lake used to be open, and a player with no way across simply waded to the
        /// middle of it and fell out of the world. Turning them back after the fact was the
        /// first repair and is the wrong shape: they have already stepped into the lake and
        /// been moved by something they did not do. The series never lets the step happen,
        /// so neither does this.
        ///
        /// Flowing water used to be exempt from all of that, on the reasoning that a stream
        /// is crossed rather than kept out of and that walling it would close the route's only
        /// gate. What the exemption actually produced was a player standing in the stream a
        /// metre below the bank, unable to climb out, over and over — so the exemption is
        /// gone and every body of water is walled. The worry behind it was the right worry
        /// and it is answered here rather than dodged: the curtain is cut where a crossing
        /// meets the water, so a bridge deck stays walkable and the rest of both banks is a
        /// wall. The hole comes from the crossing's own footprint, so moving or re-authoring
        /// one moves its gap with it and a regenerated level needs no second edit here — and
        /// a crossing that turns out not to reach both banks is reported rather than honoured,
        /// because half a gate is only a way into the water.
        ///
        /// The wall is not a permanent rule, and that is the other half of what the water
        /// teaches: it carries <see cref="WaterEdge"/>, which takes it away entirely once the
        /// party holds a Pokémon that can carry the player over. Closed until it is earned,
        /// then open everywhere at once.
        ///
        /// The wall is derived from the water mesh's own boundary — the edges belonging to
        /// exactly one triangle — rather than from the shore polygon, because the two are
        /// authored separately and would drift apart. One combined curtain mesh is used
        /// instead of a collider per edge: a lake this size has hundreds of boundary edges,
        /// and hundreds of colliders to stop the player entering water they should not be
        /// in is a poor trade.
        /// </summary>
        private static void BuildShoreline(WaterSurface body, Mesh surface, Transform parent,
            List<Crossing> crossings)
        {
            const float WallHeight = 3f;
            const float Skirt = 1.5f;

            var triangles = surface.triangles;
            var vertices = surface.vertices;

            // An edge shared by two triangles is interior; one used once is the outline.
            var seen = new Dictionary<long, EdgeUse>(triangles.Length);
            for (var i = 0; i < triangles.Length; i += 3)
            {
                AddEdge(seen, triangles[i],     triangles[i + 1], triangles[i + 2]);
                AddEdge(seen, triangles[i + 1], triangles[i + 2], triangles[i]);
                AddEdge(seen, triangles[i + 2], triangles[i],     triangles[i + 1]);
            }

            // Two passes over the outline, and the first one cuts nothing.
            //
            // A hole is only worth having if the crossing that asks for it reaches both banks.
            // One that lands on the near bank and stops is not a way over — it is an opening
            // in the wall that leads into the water and back out nowhere, which is precisely
            // the trap being closed here. So the first pass only tallies, by which end of each
            // crossing the overlap fell on, and the second honours the crossings that came out
            // with both ends and runs the curtain straight past the rest.
            var openedNear = new int[crossings.Count];
            var openedFar = new int[crossings.Count];
            var boundaryEdges = 0;
            foreach (var pair in seen)
            {
                if (pair.Value.Count != 1) continue;
                boundaryEdges++;
                TallyCrossings(crossings,
                               vertices[(int)(pair.Key >> 32)],
                               vertices[(int)(pair.Key & 0xFFFFFFFF)],
                               openedNear, openedFar);
            }

            var gates = new bool[crossings.Count];
            var gateCount = 0;
            for (var i = 0; i < crossings.Count; i++)
            {
                gates[i] = openedNear[i] > 0 && openedFar[i] > 0;
                if (gates[i]) gateCount++;
            }

            var wallVerts = new List<Vector3>();
            var wallTris = new List<int>();
            foreach (var pair in seen)
            {
                if (pair.Value.Count != 1) continue;
                var a = vertices[(int)(pair.Key >> 32)];
                var b = vertices[(int)(pair.Key & 0xFFFFFFFF)];

                if (OpenedByGate(crossings, gates, a, b)) continue;

                var baseIndex = wallVerts.Count;
                wallVerts.Add(a + Vector3.down * Skirt);
                wallVerts.Add(b + Vector3.down * Skirt);
                wallVerts.Add(a + Vector3.up * WallHeight);
                wallVerts.Add(b + Vector3.up * WallHeight);

                // Faced outward, away from the water, and one-sided.
                //
                // This used to carry both windings so that the curtain stopped anything from
                // either side, and that is the thing to avoid rather than the thing to want:
                // PhysX gives a non-convex mesh collider one-sided contacts, so a double-faced
                // wall pins a body that has somehow got into the water instead of letting it
                // push out. Standing in the stream unable to climb out is the exact complaint
                // this change answers, and there is now a great deal more curtain to be caught
                // by. Faced outward the wall stops the player on the bank — the only side they
                // can ever walk at it from — and anything a warp or a lapsed surf leaves in the
                // water walks out through the back.
                //
                // Which way is out is local evidence, not a guess: the edge belongs to exactly
                // one triangle, and that triangle's third corner is water, so out is the side
                // that corner is not on.
                var span = b - a;
                var lean = Vector3.Dot(new Vector3(span.z, 0f, -span.x).normalized,
                                       (a + b) * 0.5f - vertices[pair.Value.Opposite]);

                if (lean > EdgeSideEpsilon)
                    wallTris.AddRange(new[] { baseIndex, baseIndex + 2, baseIndex + 1,
                                              baseIndex + 2, baseIndex + 3, baseIndex + 1 });
                else if (lean < -EdgeSideEpsilon)
                    wallTris.AddRange(new[] { baseIndex + 1, baseIndex + 2, baseIndex,
                                              baseIndex + 1, baseIndex + 3, baseIndex + 2 });
                else
                    // The third corner sits on the edge's own line, so the triangle is a
                    // sliver with no side to report. Both windings there: a handful of
                    // double-faced quads cost nothing, and one quad facing into the lake is a
                    // hole in the wall.
                    wallTris.AddRange(new[] { baseIndex, baseIndex + 2, baseIndex + 1,
                                              baseIndex + 2, baseIndex + 3, baseIndex + 1,
                                              baseIndex + 1, baseIndex + 2, baseIndex,
                                              baseIndex + 1, baseIndex + 3, baseIndex + 2 });
            }

            if (boundaryEdges == 0)
            {
                Debug.LogWarning($"[Level] {body.name} has no boundary edges, so no shoreline " +
                                 "was built and the player can walk straight into it.");
                return;
            }

            ReportCrossings(body, vertices, crossings, openedNear, openedFar,
                            gateCount, boundaryEdges, wallVerts.Count / 4);

            if (wallVerts.Count == 0)
            {
                // Every single edge fell inside a gate's footprint. That is not a gate in a
                // wall, it is no wall, and it means a crossing has been authored far larger
                // than the water it spans.
                Debug.LogWarning($"[Level] Every one of {body.name}'s {boundaryEdges} boundary " +
                                 "edge(s) sits inside a crossing's footprint, so no shoreline " +
                                 "was built at all and the player can walk straight into it. " +
                                 "A crossing is measuring far wider than the water it spans.");
                return;
            }

            var wallMesh = new Mesh { name = body.name + "_Shoreline" };
            wallMesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
            wallMesh.SetVertices(wallVerts);
            wallMesh.SetTriangles(wallTris, 0);
            wallMesh.RecalculateBounds();

            var wall = new GameObject(body.name + "_Shoreline");
            wall.transform.SetParent(parent, false);
            // No renderer at all. A wall the player can see is a wall they will test.
            var collider = wall.AddComponent<MeshCollider>();
            collider.sharedMesh = wallMesh;
            collider.convex = false;
            wall.AddComponent<PokeLab.Overworld.WaterEdge>();
            wall.isStatic = true;
            SetLayer(wall, "Environment");
        }

        /// <summary>
        /// How many triangles claimed an edge, and the corner of the last one that did not
        /// touch it.
        ///
        /// The count is what says whether the edge is on the outline. The third corner is what
        /// says which side of it the water lies on, and it is kept per edge rather than taken
        /// from the mesh's overall winding because the key below deliberately throws that
        /// winding away — and because a stream is a ribbon whose two banks run in opposite
        /// directions, so exactly half of its boundary would come out facing the wrong way if
        /// one global answer were assumed.
        /// </summary>
        private struct EdgeUse
        {
            public int Count;
            public int Opposite;
        }

        /// <summary>
        /// How far off the edge's own line the water-side corner has to be, in metres, before
        /// its direction is trusted to face the curtain. Below this the triangle is a sliver
        /// and both windings are emitted instead; the tightest one in the field's two bodies
        /// measures 1.3 mm.
        /// </summary>
        private const float EdgeSideEpsilon = 0.001f;

        private static void AddEdge(Dictionary<long, EdgeUse> seen, int a, int b, int opposite)
        {
            // Keyed on the ordered pair so the two triangles sharing an edge land on the
            // same key whichever way round each of them wound it.
            var lo = Mathf.Min(a, b);
            var hi = Mathf.Max(a, b);
            var key = ((long)lo << 32) | (uint)hi;

            seen.TryGetValue(key, out var use);
            use.Count++;
            use.Opposite = opposite;
            seen[key] = use;
        }

        // --- ways across the water --------------------------------------------------------

        /// <summary>
        /// How far past a crossing's own geometry its hole in the shoreline reaches, in metres.
        ///
        /// Some margin is needed or the curtain closes on the deck: the wall stands at the
        /// waterline and a boundary edge that ends a hand's breadth outside the bridge still
        /// rises three metres through the plank the player is walking on. Kept small on
        /// purpose, because every centimetre of it is open waterline beside the crossing that
        /// the player could step into — at this value the gap either side of a deck is
        /// narrower than the player capsule, so there is nothing to fall through.
        /// </summary>
        private const float CrossingMarginMetres = 0.5f;

        /// <summary>
        /// What counts as a way over the water.
        ///
        /// Matched on substrings of the asset path *and* the placement name rather than on an
        /// exact list of either. The prefab is the stable half — the kit ships one bridge and
        /// one set of stepping stones — while the placement name drifts and lies: the layout's
        /// stones are called <c>Lake_SteppingStones_01</c> and parented under Lakeside while
        /// standing in the stream. Checking both means a renamed placement of a crossing asset
        /// and a new crossing asset with an honest name are each still recognised.
        ///
        /// Deliberately not a coordinate check. Two objects happen to fit the water today;
        /// wiring their positions in here would mean a regenerated level silently loses its
        /// gates, which is the failure this file exists to prevent.
        /// </summary>
        private static readonly string[] CrossingTokens = { "bridge", "stepping" };

        /// <summary>
        /// One authored way across, reduced to the flat footprint it occupies.
        ///
        /// Held in the crossing's own space — the authored rotation undone, the authored scale
        /// already folded into the extents — so testing a point is a rotation and two
        /// comparisons rather than eight transformed corners per edge.
        /// </summary>
        private readonly struct Crossing
        {
            public readonly string Name;
            private readonly Vector3 _centre;
            private readonly Quaternion _rotation;
            private readonly Vector2 _min;
            private readonly Vector2 _max;
            private readonly bool _travelAlongX;

            public Crossing(string name, Vector3 centre, Quaternion rotation,
                            Vector2 min, Vector2 max)
            {
                Name = name;
                _centre = centre;
                _rotation = rotation;
                _min = min;
                _max = max;
                // The long axis is the way you walk. Nothing in the kit is a square crossing,
                // and a bridge is nine metres by one and a half for the obvious reason.
                _travelAlongX = _max.x - _min.x >= _max.y - _min.y;
            }

            private Vector2 ToLocal(Vector3 world)
            {
                var d = Quaternion.Inverse(_rotation) * (world - _centre);
                return new Vector2(d.x, d.z);
            }

            /// <summary>Whether this footprint covers a point on the plan.</summary>
            public bool Covers(Vector3 world)
            {
                var p = ToLocal(world);
                return p.x >= _min.x && p.x <= _max.x && p.y >= _min.y && p.y <= _max.y;
            }

            /// <summary>
            /// Whether the segment a→b passes through this footprint, and if so how far along
            /// the crossing's own walking axis the overlap sits — negative at one end, positive
            /// at the other.
            ///
            /// A segment test rather than "is either end inside", because the water's boundary
            /// edges are not uniformly short: the stream's run up to 3.4 m, which is longer
            /// than a bridge deck is wide, and an edge that steps clean over the deck with both
            /// its ends on dry footprint-free ground would leave a wall standing across it.
            /// </summary>
            public bool TryClip(Vector3 a, Vector3 b, out float travel)
            {
                travel = 0f;
                var pa = ToLocal(a);
                var pb = ToLocal(b);

                var enter = 0f;
                var exit = 1f;
                if (!Slab(pa.x, pb.x - pa.x, _min.x, _max.x, ref enter, ref exit)) return false;
                if (!Slab(pa.y, pb.y - pa.y, _min.y, _max.y, ref enter, ref exit)) return false;

                var mid = Vector2.Lerp(pa, pb, (enter + exit) * 0.5f);
                travel = _travelAlongX
                    ? mid.x - (_min.x + _max.x) * 0.5f
                    : mid.y - (_min.y + _max.y) * 0.5f;
                return true;
            }

            private static bool Slab(float origin, float delta, float lo, float hi,
                                     ref float enter, ref float exit)
            {
                if (Mathf.Abs(delta) < 1e-6f) return origin >= lo && origin <= hi;

                var near = (lo - origin) / delta;
                var far = (hi - origin) / delta;
                if (near > far) { var swap = near; near = far; far = swap; }

                enter = Mathf.Max(enter, near);
                exit = Mathf.Min(exit, far);
                return enter <= exit;
            }
        }

        /// <summary>
        /// Finds every authored way across the water and measures it.
        ///
        /// The footprint is taken from the prefab's own mesh bounds put through the authored
        /// position, rotation and scale, because that is the honest answer to "where is this
        /// thing": a fixed radius would be a number chosen to fit the two objects that exist
        /// today and would be wrong the first time the emitter moves one or the kit gains a
        /// longer bridge.
        /// </summary>
        private static List<Crossing> CollectCrossings(Layout layout)
        {
            var found = new List<Crossing>();

            foreach (var entry in layout.objects ?? Array.Empty<Placement>())
            {
                if (entry == null || !IsCrossing(entry)) continue;

                var asset = AssetDatabase.LoadAssetAtPath<GameObject>(entry.prefab);
                if (asset == null || !TryAssetBounds(asset, out var bounds))
                {
                    Debug.LogWarning($"[Level] '{entry.name}' reads as a way across the water " +
                                     $"but '{entry.prefab}' has no mesh to measure, so no hole " +
                                     "is cut for it and the shoreline may run straight across " +
                                     "the deck.");
                    continue;
                }

                // Scale folded in here and not at test time; min/max are re-derived after it
                // because a negative scale swaps which corner is which.
                var scale = ToVector(entry.scale, Vector3.one);
                var lo = Vector3.Scale(bounds.min, scale);
                var hi = Vector3.Scale(bounds.max, scale);
                var margin = Vector2.one * CrossingMarginMetres;

                found.Add(new Crossing(
                    entry.name,
                    ToVector(entry.position),
                    Quaternion.Euler(ToVector(entry.rotation)),
                    new Vector2(Mathf.Min(lo.x, hi.x), Mathf.Min(lo.z, hi.z)) - margin,
                    new Vector2(Mathf.Max(lo.x, hi.x), Mathf.Max(lo.z, hi.z)) + margin));
            }

            return found;
        }

        private static bool IsCrossing(Placement entry)
        {
            foreach (var token in CrossingTokens)
                if (Mentions(entry.prefab, token) || Mentions(entry.name, token)) return true;
            return false;
        }

        private static bool Mentions(string value, string token) =>
            !string.IsNullOrEmpty(value) &&
            value.IndexOf(token, StringComparison.OrdinalIgnoreCase) >= 0;

        /// <summary>
        /// The extent of an imported model's geometry, in the asset's own root space.
        ///
        /// Read off the shared meshes rather than off <c>Renderer.bounds</c>, because a prefab
        /// asset has never been through a frame: its renderers have no evaluated world bounds
        /// to ask for, and the number that comes back is whatever the importer last left there.
        /// </summary>
        private static bool TryAssetBounds(GameObject asset, out Bounds bounds)
        {
            bounds = default;
            var any = false;
            var toRoot = asset.transform.worldToLocalMatrix;

            foreach (var filter in asset.GetComponentsInChildren<MeshFilter>(true))
            {
                var mesh = filter.sharedMesh;
                if (mesh == null) continue;

                var toAsset = toRoot * filter.transform.localToWorldMatrix;
                foreach (var corner in Corners(mesh.bounds))
                {
                    var point = toAsset.MultiplyPoint3x4(corner);
                    if (!any) { bounds = new Bounds(point, Vector3.zero); any = true; }
                    else bounds.Encapsulate(point);
                }
            }

            return any;
        }

        /// <summary>
        /// Records which end of which crossing this stretch of shoreline falls under.
        ///
        /// Every crossing is tested; there is no early exit on the first match, because the
        /// point of the pass is the tallies and not the answer. A crossing with hits at both
        /// ends spans the water and has earned its hole; one with hits at a single end stops
        /// short of the far bank and must not get one.
        /// </summary>
        private static void TallyCrossings(List<Crossing> crossings, Vector3 a, Vector3 b,
            int[] openedNear, int[] openedFar)
        {
            for (var i = 0; i < crossings.Count; i++)
            {
                if (!crossings[i].TryClip(a, b, out var travel)) continue;
                if (travel < 0f) openedNear[i]++; else openedFar[i]++;
            }
        }

        /// <summary>Whether a crossing that reaches both banks covers this stretch.</summary>
        private static bool OpenedByGate(List<Crossing> crossings, bool[] gates,
            Vector3 a, Vector3 b)
        {
            for (var i = 0; i < crossings.Count; i++)
                if (gates[i] && crossings[i].TryClip(a, b, out _)) return true;
            return false;
        }

        /// <summary>
        /// Says, at build time, whether the water that was just walled can still be got over.
        ///
        /// This exists because the failure it looks for is invisible from the editor and
        /// expensive from the game: a shoreline that closed the one route across the stream
        /// looks exactly like a shoreline that did not, and the first thing that notices is a
        /// player walking the route with nowhere to go. Anything found here is a warning and
        /// never a hard stop — a build that refuses to finish leaves no scene to go and look
        /// at, which is worse than a build that finishes and says what is wrong with it.
        ///
        /// Only crossings standing over *this* body are its business. The field authors two
        /// and both of them are on the stream, so charging the lake with the stones' problems
        /// would be a warning about the wrong water.
        /// </summary>
        private static void ReportCrossings(WaterSurface body, Vector3[] vertices,
            List<Crossing> crossings, int[] openedNear, int[] openedFar,
            int gates, int boundaryEdges, int walledEdges)
        {
            for (var i = 0; i < crossings.Count; i++)
            {
                var crossing = crossings[i];
                var near = openedNear[i];
                var far = openedFar[i];

                if (!StandsOver(crossing, vertices)) continue;

                if (near + far == 0)
                {
                    Debug.LogWarning($"[Level] '{crossing.Name}' stands over {body.name} and " +
                                     "reaches neither bank, so the shoreline runs unbroken past " +
                                     "both ends of it and it crosses nothing. Lengthen it or " +
                                     "move it in the emitter.");
                }
                else if (near == 0 || far == 0)
                {
                    Debug.LogWarning($"[Level] '{crossing.Name}' reaches only one bank of " +
                                     $"{body.name} — it falls short of the far one by more than " +
                                     $"the {CrossingMarginMetres} m margin — so no hole was cut " +
                                     "for it and the shoreline runs past on both sides. It is " +
                                     "scenery until it is lengthened or moved in the emitter; " +
                                     "opening the near bank alone would only be a way into the " +
                                     "water with no way back out of it.");
                }
            }

            if (gates == 0 && IsFlowing(body))
            {
                Debug.LogWarning($"[Level] {body.name} is flowing water — the kind the route is " +
                                 "meant to cross — and nothing cut a gate in its shoreline, so " +
                                 "it is walled bank to bank and only a Pokémon that can surf " +
                                 "gets past. If that is not intended, its crossings are " +
                                 "misplaced or missing from the layout.");
                return;
            }

            Debug.Log($"[Level] {body.name}: shoreline raised along {walledEdges} of " +
                      $"{boundaryEdges} boundary edge(s); {gates} crossing(s) left open.");
        }

        /// <summary>Whether a crossing's footprint has any of this body's water under it.</summary>
        private static bool StandsOver(Crossing crossing, Vector3[] vertices)
        {
            foreach (var vertex in vertices)
                if (crossing.Covers(vertex)) return true;
            return false;
        }

        /// <summary>
        /// Whether this is water that runs. The distinction no longer decides whether to wall
        /// a body — everything is walled — but it still decides how loudly a sealed one is
        /// reported: a lake with no way over it is a lake, and a stream with no way over it is
        /// a route with a hole in it.
        /// </summary>
        private static bool IsFlowing(WaterSurface body) =>
            string.Equals(body.kind, "flowing", StringComparison.OrdinalIgnoreCase);

        // --- scattered detail ------------------------------------------------------------

        private static void BuildFoliage(Layout layout, Transform root,
            Dictionary<string, Transform> parents, HashSet<string> missing, Stats stats)
        {
            if (layout.foliage == null) return;
            var material = AssetDatabase.LoadAssetAtPath<Material>(FoliageMaterial);
            if (material == null)
            {
                missing.Add(FoliageMaterial);
                return;
            }

            foreach (var field in layout.foliage)
            {
                if (field.groups == null || field.groups.Length == 0) continue;

                var host = new GameObject(field.name);
                host.transform.SetParent(
                    ResolveParent(root, parents, string.IsNullOrEmpty(field.parent)
                        ? "Terrain/Foliage" : field.parent), false);
                SetLayer(host, "Environment");
                var renderer = host.AddComponent<InstancedFoliage>();

                foreach (var group in field.groups)
                {
                    var mesh = LoadFirstMesh(group.prefab);
                    if (mesh == null)
                    {
                        missing.Add(group.prefab);
                        continue;
                    }

                    // Five floats per instance: x, y, z, yaw, uniform scale.
                    var stride = 5;
                    var count = group.instances.Length / stride;
                    var transforms = new List<Matrix4x4>(count);
                    for (var i = 0; i < count; i++)
                    {
                        var o = i * stride;
                        transforms.Add(Matrix4x4.TRS(
                            new Vector3(group.instances[o], group.instances[o + 1], group.instances[o + 2]),
                            Quaternion.Euler(0f, group.instances[o + 3], 0f),
                            Vector3.one * group.instances[o + 4]));
                    }

                    renderer.SetGroup(mesh, material, transforms);
                    stats.FoliageInstances += count;
                    stats.FoliageGroups++;
                }
            }
        }

        /// <summary>
        /// Pulls the mesh out of an imported FBX. Instancing needs the mesh and a shared
        /// material, not a prefab: a prefab would drag along its own renderer settings and
        /// there would be nothing to instance.
        /// </summary>
        private static Mesh LoadFirstMesh(string path)
        {
            foreach (var asset in AssetDatabase.LoadAllAssetsAtPath(path))
                if (asset is Mesh mesh) return mesh;
            return null;
        }

        private static void BuildTallGrass(Layout layout, Transform root,
            Dictionary<string, Transform> parents)
        {
            foreach (var patch in layout.tallGrass ?? Array.Empty<GrassTrigger>())
            {
                var go = new GameObject(patch.name);
                go.transform.SetParent(ResolveParent(root, parents, "Gameplay/TallGrass"), false);
                go.transform.localPosition = ToVector(patch.centre);

                var box = go.AddComponent<BoxCollider>();
                box.size = ToVector(patch.triggerSize, Vector3.one);
                box.isTrigger = true;

                go.AddComponent<PokeLab.Overworld.TallGrassPatch>();
                SetLayer(go, "ZoneTrigger");
            }
        }

        private static void BuildCaveEntrances(Layout layout, Transform root,
            Dictionary<string, Transform> parents)
        {
            foreach (var entrance in layout.caveEntrances ?? Array.Empty<CaveEntrance>())
            {
                // Caves are their own scenes, so the overworld carries only the doorway.
                // Nothing inside a cave is emitted into this build at all: the height grid
                // describes the mountain's outside, so an interior prop placed here would
                // sit on the summit above the chamber it belongs to.
                var go = new GameObject($"CaveEntrance_{entrance.name}");
                go.transform.SetParent(ResolveParent(root, parents, "Gameplay/Transitions"), false);
                go.transform.localPosition = ToVector(entrance.position);
                go.transform.localEulerAngles = new Vector3(0f, entrance.facingYaw, 0f);

                var box = go.AddComponent<BoxCollider>();
                box.size = ToVector(entrance.size, Vector3.one);
                box.center = new Vector3(0f, box.size.y * 0.5f, 0f);
                box.isTrigger = true;

                // The trigger was the whole of it, so walking into a cave did nothing.
                if (!string.IsNullOrEmpty(entrance.scene))
                    go.AddComponent<LevelTransition>().Configure(entrance.scene, "Spawn_FromOverworld");

                SetLayer(go, "ZoneTrigger");
                BuildCaveBlackout(entrance, go.transform);
            }
        }

        /// <summary>
        /// Fills the cave mouth with black.
        ///
        /// The arch is a real tunnel — the mesh runs out over the lip and back down inside,
        /// so you can see up it — and behind that tunnel is nothing at all, because the
        /// interior is a separate scene and the height grid here describes the outside of the
        /// mountain. Looking into the mouth therefore showed the far wall of the arch and then
        /// the world beyond it, which reads as a prop stuck on a hill rather than as a way in.
        ///
        /// Unlit black rather than a dark material: a lit surface picks up the sun and the
        /// LightingDirector's ambient, and "very dark grey that changes through the day" is
        /// exactly the thing a player reads as a wall they might get past. This is the same
        /// mechanism as the building doors and the town gate.
        /// </summary>
        private static void BuildCaveBlackout(CaveEntrance entrance, Transform mouth)
        {
            var size = ToVector(entrance.size, Vector3.one);

            var go = new GameObject("Blackout");
            go.transform.SetParent(mouth, false);

            // Measured in the editor against the built scene, not derived. The offset is
            // large and negative because Env_Cave_Arch's pivot sits about 1.95 m in front
            // of its own mouth plane -- build_layout.py's cave-shelf comment says so, and it
            // is why cutting the shelf only forward left the arch buried. A blackout placed
            // a polite 0.9 m "into" the opening therefore lands well outside it, in front of
            // the stone, reading as a black disc stuck on the cliff.
            go.transform.localPosition = new Vector3(BlackoutOffset.x,
                                                     size.y * 0.5f,
                                                     BlackoutOffset.z);
            go.transform.localRotation = Quaternion.Euler(0f, 180f, 0f);

            var mesh = new Mesh { name = "CaveBlackout" };
            var halfX = size.x * 0.5f;
            var halfY = size.y * 0.5f;
            mesh.vertices = new[]
            {
                new Vector3(-halfX, -halfY, 0f), new Vector3(halfX, -halfY, 0f),
                new Vector3(-halfX,  halfY, 0f), new Vector3(halfX,  halfY, 0f),
            };
            mesh.uv = new[] { Vector2.zero, Vector2.right, Vector2.up, Vector2.one };
            // Wound both ways. The mouth is approached from outside but a scene link can put
            // the player behind it, and a one-sided plane is invisible from there.
            mesh.triangles = new[] { 0, 2, 1, 2, 3, 1, 1, 2, 0, 1, 3, 2 };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();

            go.AddComponent<MeshFilter>().sharedMesh = mesh;
            var renderer = go.AddComponent<MeshRenderer>();
            renderer.sharedMaterial = BlackoutMaterial();
            renderer.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            renderer.receiveShadows = false;
        }

        /// <summary>
        /// Where the blackout sits relative to the cave entrance marker, in that marker's
        /// local space. Y is taken from the entrance's own height instead, so a taller mouth
        /// still fills.
        /// </summary>
        private static readonly Vector3 BlackoutOffset = new Vector3(-0.25f, 0f, -2.77f);

        private static Material s_blackout;

        private static Material BlackoutMaterial()
        {
            if (s_blackout != null) return s_blackout;

            var shader = Shader.Find("Universal Render Pipeline/Unlit") ?? Shader.Find("Unlit/Color");
            s_blackout = new Material(shader) { name = "~Blackout" };
            if (s_blackout.HasProperty("_BaseColor")) s_blackout.SetColor("_BaseColor", Color.black);
            if (s_blackout.HasProperty("_Color")) s_blackout.SetColor("_Color", Color.black);
            return s_blackout;
        }

        /// <summary>
        /// The doors out of this scene. Same machinery as a cave mouth, because they are
        /// the same thing: a volume you walk into that loads somewhere else.
        /// </summary>
        /// <summary>
        /// Ground height at a world position, read from the same baked grid the emitter
        /// placed every object with.
        ///
        /// Sampled rather than raycast because the answer has to be the one the emitter
        /// used. A raycast would hit whatever collider happens to be there — a rock, a
        /// building's plinth, the water surface — and put a marker on top of it.
        /// </summary>
        private static bool TrySampleGround(Layout layout, float x, float z, out float y)
        {
            y = 0f;
            var grid = layout.heightGrid;
            if (grid?.heights == null || grid.countX < 2 || grid.countZ < 2 || grid.step <= 0f)
                return false;

            var fx = Mathf.Clamp((x - grid.originX) / grid.step, 0f, grid.countX - 1.001f);
            var fz = Mathf.Clamp((z - grid.originZ) / grid.step, 0f, grid.countZ - 1.001f);
            var ix = Mathf.FloorToInt(fx);
            var iz = Mathf.FloorToInt(fz);
            var tx = fx - ix;
            var tz = fz - iz;

            float At(int cx, int cz)
            {
                var index = cz * grid.countX + cx;
                return index >= 0 && index < grid.heights.Length ? grid.heights[index] : 0f;
            }

            // Bilinear, matching worldgen.BakedField.at -- every object's Y came from this
            // exact interpolation, so a marker placed any other way sits at a different
            // height from the props beside it.
            var h0 = Mathf.Lerp(At(ix, iz), At(ix + 1, iz), tx);
            var h1 = Mathf.Lerp(At(ix, iz + 1), At(ix + 1, iz + 1), tx);
            y = Mathf.Lerp(h0, h1, tz);
            return true;
        }

        private static Vector3 SeatOnGround(Layout layout, Vector3 position)
        {
            if (TrySampleGround(layout, position.x, position.z, out var y))
                position.y = y;
            return position;
        }

        private static void BuildSceneLinks(Layout layout, Transform root,
            Dictionary<string, Transform> parents)
        {
            foreach (var link in layout.sceneLinks ?? Array.Empty<SceneLink>())
            {
                var go = new GameObject($"To_{link.scene}");
                go.transform.SetParent(ResolveParent(root, parents, "Gameplay/Transitions"), false);
                go.transform.localPosition = ToVector(link.position);
                go.transform.localEulerAngles = new Vector3(0f, link.facingYaw, 0f);

                var box = go.AddComponent<BoxCollider>();
                box.size = ToVector(link.size, Vector3.one);
                box.center = new Vector3(0f, box.size.y * 0.5f, 0f);
                box.isTrigger = true;

                go.AddComponent<LevelTransition>().Configure(link.scene, link.arrivalSpawn);
                SetLayer(go, "ZoneTrigger");

                // Where the player is put down arriving from the other side. Resolved by
                // name across the load, so neither scene holds a reference into the other.
                //
                // Named for where the traveller came *from*, which is the other end of this
                // link. `link.arrivalSpawn` is the name the destination must host, not this
                // scene — building it here put Spawn_FromTown in Town and Spawn_FromField in
                // Field, so each scene held the marker the other one needed and every
                // transition landed the player at the origin.
                var arrival = new GameObject($"Spawn_From{link.scene}");
                arrival.transform.SetParent(ResolveParent(root, parents, "Gameplay/Arrivals"), false);
                // Seated on the ground, not left at the door's height. The link volume sits
                // at the doorway, and 2.5 m back from a doorway on sloped ground is a
                // different height -- so arriving put the player in the air above the far
                // side and they fell in, which is exactly what a level transition must never
                // look like.
                arrival.transform.localPosition = SeatOnGround(layout,
                    ToVector(link.position) + Quaternion.Euler(0f, link.facingYaw, 0f) * Vector3.back * 2.5f);
            }
        }

        /// <summary>
        /// How far past the door volume the doorstep the player comes back out onto sits.
        ///
        /// The volume is a metre deep and starts about 50 mm off the building's face, so
        /// anything closer than this is inside the door the player has just come out of — and
        /// arriving inside a door trigger is a loop: out of the building, straight back in,
        /// with one wipe per lap and no input that can stop it.
        /// </summary>
        private const float DoorstepMetres = 1.4f;

        /// <summary>
        /// The front doors, and the doorstep to come back out onto.
        ///
        /// The layout has carried <c>buildingDoors</c> since the emitter learned to write them
        /// — nine of them in the town, one per enterable building — and the builder's <c>Layout</c>
        /// had no field of that name, so <c>JsonUtility</c> dropped the whole array on the floor
        /// without a word. That is the whole of why no building could be entered: the data was
        /// authored, emitted and then silently discarded one layer short of the scene.
        ///
        /// Same machinery as a cave mouth and a scene seam, because it is the same thing: a
        /// volume you walk into that loads somewhere else. What a building adds is the way back.
        /// Seven of the town's doors lead to the same Interior_House, so the interior cannot
        /// hold a fixed exit — the door records the doorstep it stands on and the interior's own
        /// door reads it back.
        ///
        /// The volume is left where the emitter put it: at the foot of the entrance, outside the
        /// building's own footprint. That is deliberate and it is what makes the door work at all
        /// — the buildings are collided against their real geometry, doorway included, so a
        /// trigger anywhere inside the porch is a trigger behind a wall the player is stopped by.
        /// They walk at the door, they are taken in before they reach it.
        ///
        /// Doors whose interior scene does not exist are skipped rather than built. A door to a
        /// missing scene is not inert: LevelTransition covers the screen, fails the build-settings
        /// check and leaves the player standing in a dark frame.
        /// </summary>
        private static void BuildBuildingDoors(Layout layout, Transform root,
            Dictionary<string, Transform> parents)
        {
            var built = 0;
            var missing = new HashSet<string>();

            foreach (var door in layout.buildingDoors ?? Array.Empty<BuildingDoor>())
            {
                if (door == null || string.IsNullOrEmpty(door.name)) continue;
                if (string.IsNullOrEmpty(door.scene))
                {
                    Debug.LogWarning($"[Level] {door.name} names no interior, so it is a doorway " +
                                     "that leads nowhere. Give it a scene in the emitter.");
                    continue;
                }

                if (!File.Exists(InteriorScenePath(door.scene)))
                {
                    missing.Add(door.scene);
                    continue;
                }

                var facing = Quaternion.Euler(0f, door.facingYaw, 0f);

                var go = new GameObject(door.name);
                go.transform.SetParent(ResolveParent(root, parents, "Gameplay/Transitions"), false);
                go.transform.localPosition = ToVector(door.position);
                go.transform.localRotation = facing;

                var box = go.AddComponent<BoxCollider>();
                box.size = ToVector(door.size, new Vector3(1.6f, 2.4f, 1f));
                box.center = new Vector3(0f, box.size.y * 0.5f, 0f);
                box.isTrigger = true;

                // Named for the door rather than for the building, because the name is resolved
                // by GameObject.Find on the far side of a scene load and two markers that differ
                // only by which of them was built first is the kind of collision that lands the
                // player outside the wrong house.
                var doorstep = "Spawn_Outside_" + door.name;

                go.AddComponent<LevelTransition>().ConfigureDoor(
                    door.scene,
                    string.IsNullOrEmpty(door.arrivalSpawn) ? "Spawn_FromDoor" : door.arrivalSpawn,
                    layout.scene, doorstep);
                SetLayer(go, "ZoneTrigger");

                // The door's own yaw points out of the building — the emitter offsets the volume
                // along it to stand it clear of the front wall — so the same rotation is both
                // "further out" and "facing away from the door you just came out of".
                var back = new GameObject(doorstep);
                back.transform.SetParent(ResolveParent(root, parents, "Gameplay/Arrivals"), false);
                back.transform.localPosition = SeatOnGround(layout,
                    ToVector(door.position) + facing * Vector3.forward * DoorstepMetres);
                back.transform.localRotation = facing;

                built++;
            }

            if (missing.Count > 0)
            {
                Debug.LogWarning($"[Level] {missing.Count} interior scene(s) do not exist, so the " +
                                 "doors that lead to them were not built and those buildings stay " +
                                 "shut:\n  " + string.Join("\n  ", missing) +
                                 "\nRun Tools/Poké Lab/Rebuild/Create Interior Scenes.");
            }
            if (built > 0) Debug.Log($"[Level] {built} building door(s) open onto an interior.");
        }

        private static string InteriorScenePath(string scene) =>
            "Assets/Game/Scenes/" + scene + ".unity";

        /// <summary>
        /// Stands the authored residents and trainers up in the world.
        ///
        /// Nothing was doing this. Six NPCs and four trainers are authored in the layout
        /// with positions, schedules and sight cones, the sprite pipeline has finished
        /// sixteen characters, and the scene came up empty every time — two separate
        /// workstreams reported it independently as "the level has no people".
        ///
        /// They are built as bare transforms carrying their controller. The visual is a
        /// billboarded sprite bound at runtime from the person manifest, which is why
        /// there is no prefab to instantiate: a prefab per character would be sixteen
        /// assets that only differ by which sheet they name.
        /// </summary>
        private static void BuildPeople(Layout layout, Transform root,
            Dictionary<string, Transform> parents)
        {
            foreach (var npc in layout.npcs ?? Array.Empty<NpcRecord>())
            {
                var go = new GameObject(npc.name);
                go.transform.SetParent(ResolveParent(root, parents, "Gameplay/Npcs"), false);
                go.transform.localPosition = ToVector(npc.position);
                go.transform.localEulerAngles = ToVector(npc.rotation);

                var body = go.AddComponent<CapsuleCollider>();
                body.height = 1.7f;
                body.radius = 0.28f;
                body.center = new Vector3(0f, 0.85f, 0f);

                var controller = go.AddComponent<NpcController>();
                controller.Configure(npc.npcId, npc.displayName,
                                     ToSchedule(npc.schedule, go.transform));
                AttachSprite(go, npc.spriteKey, npc.name);
                SetLayer(go, "Interactable");
                TrySetTag(go, "Interactable");
            }

            foreach (var trainer in layout.trainers ?? Array.Empty<TrainerRecord>())
            {
                var go = new GameObject(trainer.name);
                go.transform.SetParent(ResolveParent(root, parents, "Gameplay/Trainers"), false);
                go.transform.localPosition = ToVector(trainer.position);
                go.transform.localEulerAngles = ToVector(trainer.rotation);

                var body = go.AddComponent<CapsuleCollider>();
                body.height = 1.7f;
                body.radius = 0.28f;
                body.center = new Vector3(0f, 0.85f, 0f);

                go.AddComponent<TrainerController>()
                  .Configure(trainer.trainerId, trainer.sightRange, trainer.sightHalfAngle);
                AttachSprite(go, trainer.spriteKey, trainer.name);
                SetLayer(go, "Interactable");
                TrySetTag(go, "Interactable");
            }
        }

        /// <summary>
        /// Gives a character their drawn body.
        ///
        /// Without this every NPC and every trainer is a capsule collider with a controller
        /// on it: they walk their schedules, they can be talked to, and nothing is drawn.
        /// The art and its manifest had both existed for some time; nothing read them.
        ///
        /// The key comes from the layout when the layout has one, and otherwise from the
        /// object's own name — <c>NPC_Stallholder</c> becomes "stallholder", which
        /// <see cref="PersonSpriteLibrary"/> aliases onto the drawn shopkeeper. That keeps a
        /// level rebuild from depending on an art rebuild.
        /// </summary>
        private static void AttachSprite(GameObject character, string spriteKey, string objectName)
        {
            var key = spriteKey;
            if (string.IsNullOrEmpty(key) && !string.IsNullOrEmpty(objectName))
            {
                var trimmed = objectName;
                foreach (var prefix in new[] { "NPC_", "Npc_", "Trainer_" })
                    if (trimmed.StartsWith(prefix, StringComparison.Ordinal))
                        trimmed = trimmed.Substring(prefix.Length);
                key = trimmed.ToLowerInvariant();
            }
            if (string.IsNullOrEmpty(key)) return;

            var visual = new GameObject("Visual");
            visual.transform.SetParent(character.transform, false);
            visual.AddComponent<MeshFilter>();
            visual.AddComponent<MeshRenderer>();

            var billboard = visual.AddComponent<PersonBillboard>();
            var so = new SerializedObject(billboard);
            var property = so.FindProperty("_personKey");
            if (property != null)
            {
                property.stringValue = key;
                so.ApplyModifiedPropertiesWithoutUndo();
            }
        }

        /// <summary>
        /// Turns the authored schedule into entries the controller can use.
        ///
        /// Each waypoint becomes a real Transform, because that is what
        /// NpcScheduleEntry holds — an NPC's destination is a thing in the world that can
        /// be moved, not a coordinate baked into a component. They are parented to the
        /// NPC so a rebuild takes its markers with it, and placed in world space so they
        /// stay put when the NPC walks away from them.
        /// </summary>
        private static List<NpcScheduleEntry> ToSchedule(ScheduleRecord[] records, Transform owner)
        {
            var list = new List<NpcScheduleEntry>();
            var index = 0;
            foreach (var record in records ?? Array.Empty<ScheduleRecord>())
            {
                var marker = new GameObject($"Waypoint_{index:D2}_{record.activity}");
                marker.transform.SetParent(owner, false);
                marker.transform.position = ToVector(record.waypoint, owner.position);

                list.Add(new NpcScheduleEntry
                {
                    StartHour = record.startHour,
                    Activity = ParseActivity(record.activity),
                    Waypoint = marker.transform,
                    WanderRadius = record.wanderRadius,
                });
                index++;
            }
            return list;
        }

        private static NpcActivity ParseActivity(string value) =>
            Enum.TryParse<NpcActivity>(value, true, out var parsed) ? parsed : NpcActivity.Idle;

        // --- props, anchors, spawn -------------------------------------------------------

        private static void BuildObjects(Layout layout, Transform root,
            Dictionary<string, Transform> parents, HashSet<string> missing)
        {
            var objects = layout.objects ?? Array.Empty<Placement>();
            var cache = new Dictionary<string, GameObject>();

            for (var i = 0; i < objects.Length; i++)
            {
                if ((i & 127) == 0 &&
                    EditorUtility.DisplayCancelableProgressBar(
                        "Building level", $"{i} / {objects.Length}", i / (float)objects.Length))
                {
                    Debug.LogWarning("[Level] Build cancelled; the scene is incomplete.");
                    return;
                }

                var entry = objects[i];
                if (string.IsNullOrEmpty(entry.prefab)) continue;

                if (!cache.TryGetValue(entry.prefab, out var prefab))
                {
                    prefab = AssetDatabase.LoadAssetAtPath<GameObject>(entry.prefab);
                    cache[entry.prefab] = prefab;
                }

                if (prefab == null)
                {
                    missing.Add(entry.prefab);
                    continue;
                }

                var instance = (GameObject)PrefabUtility.InstantiatePrefab(
                    prefab, ResolveParent(root, parents, entry.parent));
                if (instance == null) continue;

                instance.name = entry.name;
                instance.transform.localPosition = ToVector(entry.position);
                instance.transform.localEulerAngles = ToVector(entry.rotation);
                instance.transform.localScale = ToVector(entry.scale, Vector3.one);
                if (string.IsNullOrEmpty(entry.pickup))
                {
                    instance.isStatic = entry.@static;
                    AddCollision(instance, entry.collider);
                }
                else
                {
                    // Never static. A pickup is the one prop in the level that is meant to
                    // stop existing, and the static flags are a promise that it will not —
                    // batched into a combined mesh, baked into the navmesh, and carved out
                    // of the walkable surface it is lying on.
                    instance.isStatic = false;
                    AttachPickup(instance, entry.pickup);
                }
                if (!string.IsNullOrEmpty(entry.layer)) SetLayer(instance, entry.layer);
                if (!string.IsNullOrEmpty(entry.tag) && entry.tag != "Untagged")
                    TrySetTag(instance, entry.tag);
            }
        }

        /// <summary>
        /// Gives a placed object something to collide with.
        ///
        /// Instantiating an FBX gives renderers and no colliders, and nothing was adding
        /// any: every tree, house, rock and the bridge could be walked straight through,
        /// and the only solid things in the level were the ground mesh and the trigger
        /// volumes. The bridge is the one that bites hardest — the terrain dives into the
        /// stream channel beneath it, so without a deck to stand on the player walks the
        /// route straight into the water.
        ///
        /// Trees get a capsule on the stem rather than a collider around their geometry.
        /// A mesh collider on a broadleaf is a four-metre canopy you cannot walk under,
        /// which would wall off most of the route.
        /// </summary>
        private static void AddCollision(GameObject instance, string kind)
        {
            if (string.IsNullOrEmpty(kind) || kind == "none") return;

            if (kind == "trunk")
            {
                var bounds = LocalBounds(instance);
                if (bounds.size.y <= 0.01f) return;

                var capsule = instance.AddComponent<CapsuleCollider>();
                capsule.direction = 1; // Y
                capsule.height = bounds.size.y;
                capsule.center = new Vector3(0f, bounds.min.y + bounds.size.y * 0.5f, 0f);
                // A fraction of the canopy, because the canopy is what the bounding box
                // measures and the trunk is what you walk into.
                capsule.radius = Mathf.Max(0.18f,
                    Mathf.Min(bounds.size.x, bounds.size.z) * 0.13f);
                return;
            }

            foreach (var filter in instance.GetComponentsInChildren<MeshFilter>(true))
            {
                if (filter.sharedMesh == null) continue;
                var collider = filter.gameObject.AddComponent<MeshCollider>();
                collider.sharedMesh = filter.sharedMesh;
                collider.convex = false;   // static geometry; concave is free here
            }
        }

        /// <summary>
        /// How far from an item ball the interaction prompt should reach, in metres.
        ///
        /// The ball's own geometry is 0.28 m across. A collider that size is a target the
        /// player has to stand on top of, and <see cref="PlayerInteractor"/> scores by the
        /// collider's *centre*, so widening the trigger moves nothing — it only decides how
        /// close you have to get before the game offers you the item.
        /// </summary>
        private const float PickupReachMetres = 0.6f;

        /// <summary>
        /// Turns a placed prop into something the player can collect.
        ///
        /// Three parts, and each of them is why the layout carries a <c>pickup</c> field at
        /// all rather than this being hand-wiring in the scene: the highlight that says the
        /// prop is an item, the trigger the interaction ray can find, and the component that
        /// actually moves it into the bag.
        ///
        /// The trigger replaces the emitted collider rather than joining it. An item ball is
        /// solid geometry standing in the middle of its own reward, so a real collider is
        /// something the player bumps into while walking up to it — and it vanishes the
        /// instant the item is taken, which is a solid the character controller was standing
        /// against one frame and through the next.
        ///
        /// The glow goes on the renderer, not on the root. <see cref="PickupGlow"/> writes a
        /// MaterialPropertyBlock, which is per renderer, and it requires one on its own
        /// GameObject; an FBX instance keeps its mesh on a child.
        /// </summary>
        private static void AttachPickup(GameObject instance, string itemId)
        {
            var bounds = LocalBounds(instance);
            var scale = Mathf.Max(0.01f, instance.transform.lossyScale.x);

            var trigger = instance.AddComponent<SphereCollider>();
            trigger.isTrigger = true;
            trigger.center = bounds.center;
            trigger.radius = Mathf.Max(bounds.extents.magnitude, PickupReachMetres / scale);

            instance.AddComponent<ItemPickup>().ItemId = itemId;

            var renderer = instance.GetComponentInChildren<Renderer>();
            if (renderer == null)
            {
                Debug.LogWarning($"[Level] {instance.name} grants '{itemId}' but has no " +
                                 "renderer to light up, so it will read as scenery.", instance);
                return;
            }
            renderer.gameObject.AddComponent<PickupGlow>();
        }

        /// <summary>Bounds of every renderer, in the instance's own space.</summary>
        private static Bounds LocalBounds(GameObject instance)
        {
            var renderers = instance.GetComponentsInChildren<Renderer>(true);
            if (renderers.Length == 0) return new Bounds(Vector3.zero, Vector3.zero);

            var toLocal = instance.transform.worldToLocalMatrix;
            var bounds = new Bounds(
                toLocal.MultiplyPoint3x4(renderers[0].bounds.center), Vector3.zero);
            foreach (var renderer in renderers)
            {
                var b = renderer.bounds;
                foreach (var corner in Corners(b))
                    bounds.Encapsulate(toLocal.MultiplyPoint3x4(corner));
            }
            return bounds;
        }

        private static IEnumerable<Vector3> Corners(Bounds b)
        {
            var min = b.min;
            var max = b.max;
            yield return new Vector3(min.x, min.y, min.z);
            yield return new Vector3(max.x, min.y, min.z);
            yield return new Vector3(min.x, min.y, max.z);
            yield return new Vector3(max.x, min.y, max.z);
            yield return new Vector3(min.x, max.y, min.z);
            yield return new Vector3(max.x, max.y, min.z);
            yield return new Vector3(min.x, max.y, max.z);
            yield return new Vector3(max.x, max.y, max.z);
        }

        /// <summary>
        /// Builds the invisible walls that close the town.
        ///
        /// The boundary wood is drawn as instanced foliage, which means it has no colliders
        /// at all — <c>Graphics.DrawMeshInstanced</c> submits geometry to the renderer and
        /// nothing else. Five hundred tree colliders would be the obvious answer and is the
        /// wrong one: it is five hundred physics bodies to stop the player walking into a
        /// wall they should never be able to reach, and the gaps between round trunks would
        /// still let them wedge through. So the wood is scenery and these boxes are the
        /// boundary, overlapped at every turn so the run has no seams.
        ///
        /// They carry no renderer deliberately. A barrier the player can see is a barrier
        /// they will test.
        /// </summary>
        private static void BuildBarriers(Layout layout, Transform root,
            Dictionary<string, Transform> parents)
        {
            foreach (var volume in layout.barrierVolumes ?? Array.Empty<BarrierVolume>())
            {
                var go = new GameObject(volume.name);
                go.transform.SetParent(ResolveParent(root, parents, "Barriers"), false);
                go.transform.localPosition = ToVector(volume.centre);
                go.transform.localRotation = Quaternion.Euler(0f, volume.yawDegrees, 0f);

                var box = go.AddComponent<BoxCollider>();
                // The emitter gives full extents and sinks the box a metre into the ground,
                // so the centre is already where it belongs — no half-height offset here.
                box.size = ToVector(volume.size, Vector3.one);

                SetLayer(go, string.IsNullOrEmpty(volume.layer) ? "Environment" : volume.layer);
            }
        }

        private static void BuildAnchors(Layout layout, Transform root,
            Dictionary<string, Transform> parents)
        {
            foreach (var anchor in layout.ambientAnchors ?? Array.Empty<Anchor>())
            {
                // Anchors are empties. The VFX and audio directors resolve them by name and
                // attach their own emitters, so placing a live effect here would double up.
                var go = new GameObject($"Anchor_{anchor.type}_{anchor.name}");
                go.transform.SetParent(ResolveParent(root, parents, "Ambient"), false);
                go.transform.localPosition = ToVector(anchor.position);
            }
        }

        /// <summary>
        /// The marker the player rig starts from when this scene is opened on its own.
        ///
        /// Only the town layout authors one; the field's is empty, because the field is
        /// designed to be walked into rather than started in. Left at the layout's value
        /// that puts the spawn at the world origin, which on this map is open air — and a
        /// scene opened for a five-second check is exactly when nobody is watching for it.
        /// So an unspecified spawn falls back to a door: arriving on the town's doorstep is
        /// a defensible place to be when nothing said otherwise.
        /// </summary>
        private static void BuildSpawn(Layout layout, Transform root)
        {
            var spawn = new GameObject("PlayerSpawn");
            spawn.transform.SetParent(root, false);

            var authored = ToVector(layout.playerSpawn, Vector3.zero);
            if (authored == Vector3.zero)
            {
                var link = layout.sceneLinks != null && layout.sceneLinks.Length > 0
                    ? layout.sceneLinks[0]
                    : null;
                if (link != null)
                {
                    authored = ToVector(link.position)
                               + Quaternion.Euler(0f, link.facingYaw, 0f) * Vector3.back * 2.5f;
                    Debug.Log($"[Level] '{layout.scene}' authors no player spawn; using the " +
                              $"{link.name} doorway at {authored}.");
                }
                else
                {
                    Debug.LogWarning($"[Level] '{layout.scene}' has neither a player spawn nor " +
                                     "a scene link, so opening it alone drops the player at the " +
                                     "origin.");
                }
            }

            spawn.transform.localPosition = SeatOnGround(layout, authored);
        }

        private const string CastPath = "Assets/Game/Data/Story/cast.json";

        /// <summary>
        /// Stands up the markers and people the story names but the level layout does not
        /// author.
        ///
        /// The two files are written by different hands: the layout is generated from a
        /// seeded design script, while cast.json is written by whoever writes the episodes.
        /// The episodes name camera marks, actor destinations, the trigger objects the beats
        /// hang off, one professor and one bag; the layout knows about none of them, so every
        /// CameraTo and MoveActor beat degraded to a warning and the shots the town and the
        /// lake bank were composed around were never taken.
        ///
        /// Read here rather than folded into the emitter because these are narrative
        /// positions, not level design: they move when the script moves, and a level rebuild
        /// should not be the thing that carries a rewrite.
        ///
        /// <paramref name="band"/> is what keeps each of them to one copy. cast.json is one
        /// file describing one world, but the world ships as two scenes that WorldStreamer
        /// loads together over a ten-metre overlap, and this ran unfiltered in both — so
        /// NPC_Professor and all ten marks were built into Town.unity AND Field.unity at
        /// identical coordinates, and every <c>GameObject.Find</c> in EpisodeRunner picked
        /// arbitrarily between two of them. The failure is invisible from either scene alone:
        /// each one is correct on its own, and the doubling only exists once both are loaded.
        /// Streaming will not clean it up either — <c>WorldStreamer.StripDuplicateHosts</c>
        /// drops session owners and deliberately keeps a streamed scene's people.
        /// </summary>
        private static void BuildCast(Layout layout, Transform root,
            Dictionary<string, Transform> parents, string band)
        {
            var path = Path.Combine(Directory.GetCurrentDirectory(), CastPath);
            if (!File.Exists(path))
            {
                Debug.LogWarning($"[Level] {CastPath} not found, so the episodes' camera " +
                                 "marks and the professor will not exist and every beat that " +
                                 "names one will degrade to a warning.");
                return;
            }

            Cast cast;
            try { cast = JsonUtility.FromJson<Cast>(File.ReadAllText(path)); }
            catch (Exception e)
            {
                Debug.LogWarning($"[Level] cast.json would not parse: {e.Message}");
                return;
            }

            var marks = 0;
            var skipped = 0;
            foreach (var marker in cast?.markers ?? Array.Empty<CastMarker>())
            {
                if (marker == null || string.IsNullOrEmpty(marker.name)) continue;
                if (!OwnedBy(band, marker.scene, marker.name)) { skipped++; continue; }
                if (GameObject.Find(marker.name) != null) continue;

                var go = new GameObject(marker.name);
                go.transform.SetParent(ResolveParent(root, parents, "Story/Marks"), false);
                // Authored heights are eye or head height for a camera to look at, so these
                // are taken as written rather than seated on the ground like a prop.
                go.transform.localPosition = ToVector(marker.position);
                marks++;
            }

            var people = 0;
            foreach (var speaker in cast?.speakers ?? Array.Empty<CastSpeaker>())
            {
                var required = speaker?.requiredNpc;
                if (required == null || string.IsNullOrEmpty(required.name)) continue;
                if (!OwnedBy(band, speaker.scene, required.name)) { skipped++; continue; }
                if (GameObject.Find(required.name) != null) continue;

                var go = new GameObject(required.name);
                go.transform.SetParent(ResolveParent(root, parents, "Gameplay/Npcs"), false);
                go.transform.localPosition = ToVector(required.position);
                go.transform.localEulerAngles = ToVector(required.rotation);

                var body = go.AddComponent<CapsuleCollider>();
                body.height = 1.7f;
                body.radius = 0.28f;
                body.center = new Vector3(0f, 0.85f, 0f);

                go.AddComponent<NpcController>()
                  .Configure(required.npcId, required.displayName, null);
                AttachSprite(go, speaker.spriteKey, required.name);
                SetLayer(go, "Interactable");
                TrySetTag(go, "Interactable");
                people++;

                // A mark on their own doorstep, so a scene that took them away from it has
                // somewhere to send them back to. cast.json lists only camera marks and the
                // marks of the one walk each actor makes outward; without this an actor ends
                // a scene wherever the last MoveActor left them, and any later beat that
                // assumes they went home has nowhere to send them.
                var home = new GameObject("Mark_" + required.name.Replace("NPC_", "") + "_Home");
                home.transform.SetParent(ResolveParent(root, parents, "Story/Marks"), false);
                home.transform.localPosition = ToVector(required.position);
                marks++;
            }

            var props = BuildCastProps(cast, layout, root, parents, band, ref skipped);

            if (marks + people + props + skipped > 0)
            {
                Debug.Log($"[Level] Cast: {marks} marker(s), {people} authored " +
                          $"person/people and {props} story prop(s) in '{band}'; " +
                          $"{skipped} owned by another band.");
            }
        }

        /// <summary>
        /// Stands up the story props: the things a beat asks the player to look at.
        ///
        /// A mark is an empty, and an empty is the right shape for a camera target or a
        /// destination. It is the wrong shape for a beat whose whole content is that the
        /// player can see something — <c>field_bag_left</c> says the professor has left his bag
        /// on the bank, <c>CameraTo Prop_ProfessorBag</c> takes the only close shot in the
        /// field on it, and if that object has no renderer the shot is of an empty patch of
        /// ground and the line is about nothing.
        ///
        /// Read from cast.json rather than emitted with the level for the same reason the marks
        /// are: where the bag lies is a decision the script makes, and a level regeneration
        /// should not be what carries a rewrite of the act. Built here rather than by hand in
        /// the scene because a hand-placed object in a .unity file is destroyed by the next
        /// rebuild, which is what this whole file exists to stop.
        ///
        /// No collider, deliberately. The ambusher has to walk from the grass to within 1.6 m
        /// of a player who is standing next to this thing, and a solid on that ground is a hole
        /// carved out of the navmesh exactly where the approach has to land.
        /// </summary>
        private static int BuildCastProps(Cast cast, Layout layout, Transform root,
            Dictionary<string, Transform> parents, string band, ref int skipped)
        {
            var built = 0;
            foreach (var prop in cast?.props ?? Array.Empty<CastProp>())
            {
                if (prop == null || string.IsNullOrEmpty(prop.name)) continue;
                if (!OwnedBy(band, prop.scene, prop.name)) { skipped++; continue; }
                if (GameObject.Find(prop.name) != null) continue;

                var asset = AssetDatabase.LoadAssetAtPath<GameObject>(prop.prefab);
                if (asset == null)
                {
                    Debug.LogWarning($"[Level] cast.json prop '{prop.name}' names " +
                                     $"'{prop.prefab}', which will not load. The beat that " +
                                     "frames it will point the camera at nothing.");
                    continue;
                }

                var go = (GameObject)PrefabUtility.InstantiatePrefab(
                    asset, ResolveParent(root, parents, "Story/Props"));
                if (go == null) continue;

                go.name = prop.name;
                go.transform.localScale = ToVector(prop.scale, Vector3.one);
                go.transform.localEulerAngles = ToVector(prop.rotation);
                go.transform.localPosition = SeatProp(layout, go, ToVector(prop.position));
                SetLayer(go, "Environment");
                built++;
            }
            return built;
        }

        /// <summary>How far a seated story prop is pushed into the ground, in metres.</summary>
        /// <remarks>
        /// Matches audit_placement.py's BITE. A prop seated exactly on the surface z-fights
        /// along its whole base seam, and on ground that is not flat it also shows daylight
        /// under its downhill corner.
        /// </remarks>
        private const float PropBiteMetres = 0.06f;

        /// <summary>
        /// Puts a prop on the ground by its footprint rather than by its pivot.
        ///
        /// Sampling the height under the pivot alone is the check that cannot see the failure
        /// it is meant to catch: a box pivoted at the centre of its base, on a slope, passes at
        /// exactly zero while its downhill half hangs in the air. So this takes the lowest
        /// ground under the object's real footprint, which is where the daylight would show.
        ///
        /// The height comes from the layout's baked grid, not from a raycast, so the answer is
        /// the same one every emitted object's Y was taken from. A raycast would hit whatever
        /// collider happened to be there and stand the prop on top of it.
        /// </summary>
        private static Vector3 SeatProp(Layout layout, GameObject instance, Vector3 position)
        {
            var bounds = LocalBounds(instance);
            var scale = instance.transform.lossyScale;
            var yaw = instance.transform.localEulerAngles.y;
            var rotation = Quaternion.Euler(0f, yaw, 0f);

            var lowest = float.PositiveInfinity;
            for (var ix = -1; ix <= 1; ix++)
            {
                for (var iz = -1; iz <= 1; iz++)
                {
                    var local = new Vector3(bounds.center.x + bounds.extents.x * ix, 0f,
                                            bounds.center.z + bounds.extents.z * iz);
                    var offset = rotation * Vector3.Scale(local, scale);
                    if (TrySampleGround(layout, position.x + offset.x, position.z + offset.z,
                                        out var y))
                        lowest = Mathf.Min(lowest, y);
                }
            }

            if (float.IsPositiveInfinity(lowest))
            {
                Debug.LogWarning($"[Level] '{instance.name}' could not be seated: the layout " +
                                 "carries no height grid, so it is left at its authored Y and " +
                                 "may be standing in the air.", instance);
                return position;
            }

            // The asset's own base may sit below its pivot; keep that offset or a prop modelled
            // around its centre sinks by half its height.
            position.y = lowest - bounds.min.y * scale.y - PropBiteMetres;
            return position;
        }

        /// <summary>
        /// Whether the band being built is the one that owns this cast entry.
        ///
        /// An entry with no <c>scene</c> falls to the first band rather than to all of them.
        /// Building it everywhere is what produced the duplicate this field exists to stop,
        /// and building it nowhere is worse still — a professor who is missing from the whole
        /// world fails loudly, but only at the moment the opening tries to walk him, which is
        /// after the build has already reported success. One copy in a possibly wrong band is
        /// recoverable by moving it; zero copies and two copies both are not. The warning
        /// names the entry so the missing tag is fixed rather than lived with.
        /// </summary>
        private static bool OwnedBy(string band, string owner, string entryName)
        {
            if (string.IsNullOrEmpty(owner))
            {
                owner = SceneLayouts[0].Scene;
                Debug.LogWarning($"[Level] cast.json entry '{entryName}' names no scene, so " +
                                 $"it is built into '{owner}' alone. Give it a \"scene\" or it " +
                                 "sits in whichever band happens to be listed first.");
            }
            return string.Equals(band, owner, StringComparison.OrdinalIgnoreCase);
        }

        /// <summary>
        /// Which townsperson carries which episode, and what has to be true first.
        ///
        /// This table is the thing that was missing. The episodes are authored in
        /// episodes.json, most of them behind a trigger, and <c>StoryEncounter</c> — the
        /// component written to fire them — was on nothing in either scene: a search of
        /// Town.unity and Field.unity for its guid returned the .meta file and nothing else.
        /// So the opening played, the broadcast finished, control came back, and the game had
        /// no further step of any kind. The rival stood at the lab door for the rest of the
        /// save with no reason to move.
        ///
        /// It lives here rather than in cast.json because it is a binding between scene
        /// objects and episode ids, not a narrative position, and because the town is
        /// generated: anything hung on these NPCs by hand is gone at the next rebuild.
        ///
        /// Order matters only in that each entry's <c>Requires</c> is the previous entry's
        /// completion flag, which is what keeps the act in sequence without a state machine.
        ///
        /// One entry per actor, and that is a hard rule rather than a convention:
        /// <see cref="BuildStoryTriggers"/> reuses the <c>StoryEncounter</c> it finds on the
        /// object, so a second entry naming the same actor silently replaces the first. Bram
        /// and Kes are each wanted twice; each spends his slot on the beat that has to come
        /// from the character, and the other beat hangs off a marker object standing nearby.
        ///
        /// Every episode id here must be in episodes.json. One that is not is refused by the
        /// runner, and <see cref="StoryEncounter"/> retires the beat after three refusals with
        /// an error — the act it was meant to open is then unreachable for that whole save.
        /// That is why <c>opening_departure</c> and <c>leaving_town</c> are gone from this
        /// table rather than left in place: they were retired from episodes.json with the
        /// rewrite of the opening act.
        /// </summary>
        private readonly struct StoryTrigger
        {
            public readonly string Actor;
            public readonly string EpisodeId;
            public readonly string Requires;
            public readonly string Completes;
            public readonly float Radius;
            public readonly float ApproachSeconds;

            public StoryTrigger(string actor, string episodeId, string requires, string completes,
                                float radius, float approachSeconds)
            {
                Actor = actor;
                EpisodeId = episodeId;
                Requires = requires;
                Completes = completes;
                Radius = radius;
                ApproachSeconds = approachSeconds;
            }
        }

        private static readonly StoryTrigger[] StoryTriggers =
        {
            // Bram at the head of the ramp. The refusal is on him rather than on a marker
            // because it is the one beat that has to come from the man doing the refusing.
            new StoryTrigger("NPC_GateKeeper", "gate_wait_for_kes",
                             "story.opening_seen", "story.gate_refused", 4.0f, 0f),

            // The square, as an object. Kes' own StoryEncounter slot is spent on the rival
            // battle -- BuildStoryTriggers reuses whatever component it finds, so two entries
            // naming one actor is not two beats, it is the second overwriting the first -- so
            // his send-off hangs off a marker in the square and walks him in with MoveActor.
            new StoryTrigger("Trigger_Square", "kes_summons",
                             "story.gate_refused", "story.kes_summons_done", 5.0f, 0f),

            // Bram's second beat, on its own marker for the same one-slot-per-actor reason.
            // Tight radius: it sits at the top of the ramp and must not fire from the street.
            new StoryTrigger("Trigger_GateOpen", "gate_opens",
                             "story.kes_summons_done", "story.gate_acknowledged", 3.5f, 0f),

            // Linden on the lake bank, in the Field. Gated on story.gate_open rather than on
            // the acknowledgement, because gate_opens is deliberately skippable -- the ramp is
            // already down by then -- and a player who walked past Bram must still meet him.
            // Approach is zero: he is seventy-one and mid-count, and a professor who jogs at
            // the player undoes the one joke the character has.
            new StoryTrigger("NPC_Professor", "field_professor_mutters",
                             "story.gate_open", "story.prof_mutter_done", 4.0f, 0f),

            // The bag he leaves behind, which is why this beat hangs off a prop and not a
            // person: there is nobody on the bank once he has gone.
            new StoryTrigger("Prop_ProfessorBag", "field_bag_left",
                             "story.prof_mutter_done", "story.bag_seen", 3.0f, 0f),

            // Kes, at the lake. On him and not on a marker beside him: TrainerController
            // .StandsDown reads the StoryEncounter on its own GameObject and refuses to notice
            // the player while it is pending, and it can only read one that is there. Without
            // that, the sight cone and the story beat race for who starts the fight and the
            // loser is the party built from the player's starter.
            //
            // REGATED to story.cave_act (2026-08-20), which NOTHING sets yet: the user's
            // revision has Kes leave the lake on the bet without fighting — he runs for the
            // grotto at the end of field_professor_returns — so this beat belongs to the cave
            // act, whose opener will own the flag and probably move his post with it. Gated
            // rather than deleted, so the fight and its starter-counter party wait whole.
            new StoryTrigger("NPC_Rival", "rival_first_battle",
                             "story.cave_act", "story.rival_battle_done", 5.0f, 0f),
        };

        /// <summary>Arms the authored story beats on the people who carry them.</summary>
        private static void BuildStoryTriggers()
        {
            var armed = 0;
            foreach (var trigger in StoryTriggers)
            {
                // Absent is normal, not an error: the table covers the whole slice and each
                // scene holds only its own half of the cast.
                var actor = GameObject.Find(trigger.Actor);
                if (actor == null) continue;

                var encounter = actor.GetComponent<StoryEncounter>();
                if (encounter == null) encounter = actor.AddComponent<StoryEncounter>();
                encounter.Configure(trigger.EpisodeId, trigger.Requires, trigger.Completes,
                                    trigger.Radius, trigger.ApproachSeconds);
                armed++;
            }

            if (armed > 0) Debug.Log($"[Level] Story: {armed} encounter(s) armed.");
        }

        /// <summary>
        /// Closes the way out of town until the story opens it.
        ///
        /// Built from the scene link rather than from a hand-written position, so it stays
        /// across the doorway when the emitter moves the ramp. Placed a metre to the town side
        /// of the link — in front of it, not on it — because the arrival marker for travellers
        /// coming the other way sits 2.5 m town-side, and a wall on top of that would strand
        /// anyone walking back in.
        ///
        /// Skipped in any scene with no gatekeeper in it. The route does not need a gate; it
        /// needs the town to have had one.
        /// </summary>
        private static void BuildStoryGate(Layout layout, Transform root,
            Dictionary<string, Transform> parents)
        {
            var keeper = GameObject.Find("NPC_GateKeeper");
            if (keeper == null) return;

            var link = layout.sceneLinks != null && layout.sceneLinks.Length > 0
                ? layout.sceneLinks[0]
                : null;
            if (link == null)
            {
                Debug.LogWarning("[Level] There is a gatekeeper but no scene link to stand him " +
                                 "in front of, so the way out of town is open from the first " +
                                 "frame and story.gate_open still gates nothing.");
                return;
            }

            var facing = Quaternion.Euler(0f, link.facingYaw, 0f);
            var go = new GameObject("StoryGate_TownRamp");
            go.transform.SetParent(ResolveParent(root, parents, "Story/Gates"), false);
            go.transform.localPosition = SeatOnGround(layout,
                ToVector(link.position) + facing * Vector3.back * 1.0f);
            go.transform.localRotation = facing;

            // Wider than the doorway it closes. Sized exactly to the link, a player who hugs
            // the cliff walks around the end of it, and a gate with a gap beside it is worse
            // than no gate: it reads as a bug rather than as a rule.
            var opening = ToVector(link.size, new Vector3(5f, 3f, 1.6f));
            go.AddComponent<StoryGate>().Configure("story.gate_open",
                keeper.GetComponent<NpcController>(),
                new Vector3(opening.x + 1.5f, 4f, 0.6f));

            // Kept OUT of the navmesh bake. The gate sits on Environment, a layer
            // BuildNavigation collects, so the closed wall was baked into the town mesh as
            // permanent geometry: the ramp under it was a hole no runtime flag could heal, and
            // every agent asked to leave town pathed around it into the fence — that is Kes
            // veering right at the gatekeeper. The wall blocks the PLAYER's body and nothing
            // else, by design ("플레이어만 못 지나가게 하고 에이전트는 괜찮도록"): agents
            // ignore physics colliders, the mesh stays continuous through the gate, and there
            // is deliberately no NavMeshObstacle either — see the note in StoryGate.
            var navmesh = go.AddComponent<NavMeshModifier>();
            navmesh.ignoreFromBuild = true;

            SetLayer(go, "Environment");
            Debug.Log("[Level] Story: the town ramp is closed until story.gate_open, and the " +
                      "wall no longer bakes a hole in the navmesh.");
        }

